 const pending=this.pendingSorted(),now=Date.now(),limit=now+24*60*60*1000,urgent=pending.filter(item=>item.is_overdue||new Date(item.scheduled_local||item.scheduled_for).getTime()<=limit),shown=(urgent.length?urgent:pending).slice(0,3),remaining=Math.max(0,(urgent.length?urgent:pending).length-shown.length);const urgentClass=urgent.length?"hasUrgent":"";
 return`${this.heading("overview")}<section class="actionNow ${urgentClass}"><div class="actionNowHead"><div><small>${urgent.length?this.t("within24h"):this.t("nextTasks")}</small><h2>${this.t("actionNow")}</h2></div>${urgent.length?`<strong>${urgent.length}</strong>`:""}</div>${shown.length?shown.map(item=>this.taskCompact(item)).join(""):`<div class="nothingDue"><ha-icon icon="mdi:check-circle-outline"></ha-icon><span>${this.t("nothingDue")}</span></div>`}${remaining?`<button class="moreTasks" data-view="tasks">+${remaining} ${this.t("moreTasks")}</button>`:""}</section><section class="quickCaptureCard"><h2>${this.t("quickCapture")}</h2><div class="quickCaptureGrid"><button data-action="record-weight"><ha-icon icon="mdi:scale"></ha-icon><span>${this.t("recordWeight")}</span></button><button data-action="record-symptom"><ha-icon icon="mdi:alert-circle-outline"></ha-icon><span>${this.t("recordSymptom")}</span></button><button data-action="record-product"><ha-icon icon="mdi:pill"></ha-icon><span>${this.t("recordProduct")}</span></button><button data-action="record-event"><ha-icon icon="mdi:note-plus-outline"></ha-icon><span>${this.t("recordGeneral")}</span></button><button data-action="create-task"><ha-icon icon="mdi:clipboard-plus-outline"></ha-icon><span>${this.t("createTask")}</span></button><button data-action="ai-assist"><ha-icon icon="mdi:creation-outline"></ha-icon><span>${this.t("aiAssist")}</span></button></div></section>`
