AH081.stopAIDictation=async function(button){const state=this.aiDictation;if(!state)return;this.aiDictation=null;const form=state.form;try{state.processor.disconnect();state.source.disconnect();state.mute.disconnect()}catch(_error){}for(const track of state.stream?.getTracks?.()||[])track.stop();try{await state.context.close()}catch(_error){}button.disabled=true;button.classList.remove("recording");button.innerHTML=`<ha-icon icon="mdi:progress-clock"></ha-icon><span>${this.t("aiTranscribing")}</span>`;this.notify(this.t("aiTranscribing"));try{const raw=this.flattenAudio(state.chunks);if(!raw.length)throw Error("No audio recorded");const file=this.wavFile(this.resampleAudio(raw,state.sampleRate,16000)),uploaded=await this.aiUploadOne(file),sttEntity=form.elements.ai_stt_entity_id?.value||"",language=String(this.h?.language||navigator.language||"de-CH"),result=await this.ws(`${D}/v081/transcribe`,{upload_id:uploaded.upload_id,language,...(sttEntity?{entity_id:sttEntity}:{})}),area=form.elements.ai_context;if(area&&result.text){area.value=[area.value.trim(),result.text.trim()].filter(Boolean).join("\n");this.aiContextDraft=area.value}this.aiLastSttLanguage=result.language||language;const target=form.querySelector("[data-stt-language]");if(target)target.textContent=`${this.t("sttLanguage")}: ${this.aiLastSttLanguage}`;button.disabled=false;button.dataset.action="ai-start-dictation";button.innerHTML=`<ha-icon icon="mdi:microphone-outline"></ha-icon><span>${this.t("aiDictate")}</span>`}catch(error){button.disabled=false;button.dataset.action="ai-start-dictation";button.innerHTML=`<ha-icon icon="mdi:microphone-outline"></ha-icon><span>${this.t("aiDictate")}</span>`;this.notify(`${this.t("failed")}: ${error?.message||error}`,true)}};
AH081.handleClick=async function(event){const button=event.composedPath().find(node=>node?.dataset&&(node.dataset.action||node.dataset.view)),action=button?.dataset?.action,id=button?.dataset?.id;if(action==="record-product"){this.open("record-product-081",{animalId:id||""});return}if(action==="correct-weight"){this.open("correct-weight-081",{eventId:id});return}if(action==="weight-correction-step"){const form=button.closest("form"),input=form?.elements?.weight,unit=form?.elements?.weight_unit?.value||"kg";if(!input)return;const deltaKg=Number(button.dataset.delta||0),delta=unit==="kg"?deltaKg:deltaKg*1000,decimals=unit==="kg"?2:0,current=Number(input.value||0);input.value=Math.max(unit==="kg"?.01:1,current+delta).toFixed(decimals);input.focus();return}if(action==="group-detail-081"){this.groupDetailId=id;this.view="group-detail";this.detail=null;this.render();return}if(action==="record-group-event"){this.open("record-group-event-081",{groupId:id,eventType:"observation"});return}if(action==="record-group-product"){this.open("record-group-event-081",{groupId:id,eventType:"medication"});return}if(action==="create-group-task"){this.open("create-group-task-081",{groupId:id});return}if(action==="group-pdf"){try{const result=await this.ws(`${D}/v081/group_pdf`,{group_id:id}),link=document.createElement("a");link.href=result.url;link.rel="noopener";document.body.append(link);link.click();link.remove()}catch(error){this.notify(`${this.t("failed")}: ${error?.message||error}`,true)}return}return AH081Base.handleClick.call(this,event)};
